# Customize the schema and validation for this standalone archive.
ARCHIVE_KIND = 'contacts'
ARCHIVE_FIELDS = [('name', 'Full name', 'line', True, 200, []), ('phone', 'Phone', 'line', False, 80, []), ('email', 'Email', 'line', False, 200, []), ('photo', 'Photo path (PNG/GIF)', 'line', False, 1024, []), ('notes', 'Notes', 'text', False, 10000, [])]

# Contacts are explicitly saved to a dedicated SQLite database.
def archive_extra_validate(records):
    for record in records:
        email = record["email"]
        if email and (email.count("@") != 1 or not all(email.split("@")) or any(char.isspace() for char in email)):
            raise ValueError("Enter a basic email address or leave it blank")


def archive_sort_key(record):
    return record["name"].casefold()


def archive_row_label(record):
    return record["name"][:40] + " | " + record["phone"][:25]


# Generic archive helpers are embedded in each standalone starter.
import json
import os
import re
import tempfile
import uuid
from pathlib import Path


def archive_validate_records(records):
    # Validate every record before changing the visible collection.
    if not isinstance(records, list) or len(records) > 500:
        raise ValueError("Use a list of up to 500 records")
    result, identities = [], set()
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get("id"), str) or not 1 <= len(record["id"]) <= 80 or record["id"] in identities:
            raise ValueError("Records need unique nonempty IDs")
        clean = {"id": record["id"]}
        identities.add(record["id"])
        for key, label, kind, required, limit, choices in ARCHIVE_FIELDS:
            value = record.get(key)
            if not isinstance(value, str) or len(value) > limit or (required and not value.strip()):
                raise ValueError("Invalid field: " + label)
            value = value.strip()
            if choices and value not in choices:
                raise ValueError("Choose a valid " + label)
            clean[key] = value
        result.append(clean)
    archive_extra_validate(result)
    return sorted(result, key=archive_sort_key)


def archive_render(app):
    query = app.FilterEntry.get().casefold().strip()
    app.RecordList.delete(0, "end")
    app.archive_visible = []
    for record in app.archive_records:
        if query and not any(query in record[key].casefold() for key, *_ in ARCHIVE_FIELDS):
            continue
        app.archive_visible.append(record["id"])
        app.RecordList.insert("end", archive_row_label(record))
    if app.archive_selected not in app.archive_visible:
        app.archive_selected = None
    elif app.archive_selected is not None:
        app.RecordList.selection_set(app.archive_visible.index(app.archive_selected))
    app.StatusLabel.configure(text=f"{len(app.archive_visible)} shown / {len(app.archive_records)} records | Save SQLite manually to keep changes")


def archive_clear(app):
    # Clear the editor without deleting any stored record.
    app.archive_selected = None
    app.RecordList.selection_clear(0, "end")
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        if kind == "text":
            field.delete("1.0", "end")
        elif kind == "choice":
            field.set(choices[0])
        else:
            field.delete(0, "end")
    app.StatusLabel.configure(text="New record: fill the fields and press Add")


def archive_select(app):
    selection = app.RecordList.curselection()
    if not selection or selection[0] >= len(app.archive_visible):
        return
    identity = app.archive_visible[selection[0]]
    record = next((r for r in app.archive_records if r["id"] == identity), None)
    if record is None:
        return
    app.archive_selected = identity
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        if kind == "text":
            field.delete("1.0", "end")
            field.insert("1.0", record[key])
        elif kind == "choice":
            field.set(record[key])
        else:
            field.delete(0, "end")
            field.insert(0, record[key])


def archive_collect(app, identity):
    record = {"id": identity}
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        record[key] = field.get("1.0", "end-1c") if kind == "text" else field.get()
    return record


def archive_store(app, update=False):
    # Validate a copy so invalid edits never partially replace the collection.
    if update and app.archive_selected is None:
        messagebox.showinfo("Update record", "Select a record first", parent=app.Form1)
        return
    identity = app.archive_selected if update else uuid.uuid4().hex
    candidate = [r.copy() for r in app.archive_records if not update or r["id"] != identity]
    candidate.append(archive_collect(app, identity))
    try:
        candidate = archive_validate_records(candidate)
    except ValueError as error:
        messagebox.showerror("Invalid record", str(error), parent=app.Form1)
        return
    app.archive_records = candidate
    app.archive_selected = identity
    app.FilterEntry.delete(0, "end")
    archive_render(app)


def archive_delete(app):
    if app.archive_selected is not None and messagebox.askyesno("Delete record", "Delete the selected record?", parent=app.Form1):
        app.archive_records = [r for r in app.archive_records if r["id"] != app.archive_selected]
        archive_clear(app)
        archive_render(app)






def archive_close(app):
    # There is no autosave: confirm before discarding the in-memory collection.
    if messagebox.askyesno("Close archive", "Close without saving? Use Save SQLite first to keep changes.", parent=app.Form1):
        app.root.destroy()



# SQLite adapters replace the generic JSON buttons for this starter only.
import sqlite3
import struct
import tkinter as tk

CONTACT_COLUMNS = ["id", "name", "phone", "email", "photo", "notes"]


def contacts_check_database(connection):
    # Reject unrelated databases before any write or collection replacement.
    tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")}
    if tables != {"contacts", "metadata"}:
        raise ValueError("Choose a Contact Book database, not an unrelated SQLite file")
    if connection.execute("SELECT type FROM sqlite_master WHERE type IN ('view','trigger')").fetchone():
        raise ValueError("Unexpected views or triggers in contact database")
    if connection.execute("SELECT version, kind FROM metadata").fetchall() != [(1, "contacts")]:
        raise ValueError("Unsupported contact database version")
    if [row[1] for row in connection.execute("PRAGMA table_info(contacts)")] != CONTACT_COLUMNS:
        raise ValueError("Unsupported contacts table schema")


def archive_save(app):
    # All in-memory records are committed in one transaction to a dedicated file.
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".sqlite", filetypes=[("Contact SQLite", "*.sqlite")])
    if not filename:
        return
    connection = None
    try:
        records = archive_validate_records(app.archive_records)
        path = Path(filename).resolve()
        fresh = not path.exists()
        connection = sqlite3.connect(path, timeout=3)
        connection.execute("PRAGMA trusted_schema=OFF")
        connection.execute("BEGIN IMMEDIATE")
        if fresh:
            connection.execute("CREATE TABLE metadata(version INTEGER, kind TEXT)")
            connection.execute("INSERT INTO metadata VALUES(1, 'contacts')")
            connection.execute("CREATE TABLE contacts(id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT, email TEXT, photo TEXT, notes TEXT)")
        else:
            contacts_check_database(connection)
        connection.execute("DELETE FROM contacts")
        connection.executemany("INSERT INTO contacts(id, name, phone, email, photo, notes) VALUES(?,?,?,?,?,?)", [tuple(record[key] for key in CONTACT_COLUMNS) for record in records])
        connection.commit()
        app.StatusLabel.configure(text="Contact database saved: " + str(path))
    except (OSError, ValueError, sqlite3.Error) as error:
        if connection is not None:
            connection.rollback()
        messagebox.showerror("Save contacts", str(error), parent=app.Form1)
    finally:
        if connection is not None:
            connection.close()


def archive_open(app):
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Contact SQLite", "*.sqlite *.db")])
    if not filename:
        return
    connection = None
    try:
        path = Path(filename).resolve(strict=True)
        connection = sqlite3.connect(path.as_uri() + "?mode=ro", uri=True, timeout=3)
        connection.execute("PRAGMA query_only=ON")
        connection.execute("PRAGMA trusted_schema=OFF")
        contacts_check_database(connection)
        rows = connection.execute("SELECT id, name, phone, email, photo, notes FROM contacts ORDER BY name COLLATE NOCASE LIMIT 501").fetchall()
        records = archive_validate_records([dict(zip(CONTACT_COLUMNS, row)) for row in rows])
    except (OSError, ValueError, sqlite3.Error) as error:
        messagebox.showerror("Open contacts", str(error), parent=app.Form1)
        return
    finally:
        if connection is not None:
            connection.close()
    if messagebox.askyesno("Open contacts", "Replace the collection? Save current changes first if needed.", parent=app.Form1):
        app.archive_records = records
        archive_clear(app)
        archive_render(app)
        app.PhotoPreview.configure(image="", text="Select a contact to preview its photo")
        app.contact_photo = None


def contacts_preview(app):
    # References are not embedded. Only small PNG/GIF files are previewed.
    app.contact_photo = None
    app.PhotoPreview.configure(image="", text="No photo")
    filename = app.Field3.get().strip()
    if not filename:
        return
    try:
        path = Path(filename)
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("Photo exceeds 2 MiB")
        with path.open("rb") as stream:
            header = stream.read(24)
        if header.startswith(b"\x89PNG\r\n\x1a\n") and len(header) >= 24:
            width, height = struct.unpack(">II", header[16:24])
        elif header[:6] in (b"GIF87a", b"GIF89a") and len(header) >= 10:
            width, height = struct.unpack("<HH", header[6:10])
        else:
            raise ValueError("Preview supports PNG and GIF only")
        if not 0 < width <= 4096 or not 0 < height <= 4096 or width * height > 8000000:
            raise ValueError("Photo dimensions are too large")
        image = tk.PhotoImage(master=app.Form1, file=str(path))
        image = image.subsample(max(1, (width + 159) // 160, (height + 119) // 120))
        app.contact_photo = image
        app.PhotoPreview.configure(image=image, text="")
    except (OSError, ValueError, tk.TclError) as error:
        app.PhotoPreview.configure(text=str(error))


def contacts_select(app):
    archive_select(app)
    if app.archive_selected is not None:
        contacts_preview(app)


def contacts_pick_photo(app):
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Photo PNG/GIF", "*.png *.gif")])
    if filename:
        app.Field3.delete(0, "end")
        app.Field3.insert(0, filename)
        contacts_preview(app)

